@Composable fun DirectContent(holder:DirectStateHolder,modifier:Modifier=Modifier){val scope=rememberCoroutineScope();LaunchedEffect(Unit){holder.load()};holder.selected?.let{c->Column(modifier.fillMaxSize()){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){OutlinedButton(onClick=holder::close){Text("رجوع")};Spacer(Modifier.width(10.dp));Column{Text(c.otherDisplayName?:c.otherUsername?:"مستخدم تِسوى",fontWeight=FontWeight.Bold);Text(if(c.status=="requested")"طلب مراسلة" else "محادثة مباشرة",style=MaterialTheme.typography.bodySmall)}};holder.message?.let{Text(it,Modifier.fillMaxWidth().padding(10.dp),color=MaterialTheme.colorScheme.error)};if(c.requiresAction){Surface(color=MaterialTheme.colorScheme.secondaryContainer){Column(Modifier.fillMaxWidth().padding(16.dp)){Text("الشخص ده طالب يبدأ كلام معاك.");Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={scope.launch{holder.act(true)}}){Text("قبول")};OutlinedButton(onClick={scope.launch{holder.act(false)}}){Text("تجاهل")}}}}};LazyColumn(Modifier.weight(1f).fillMaxWidth(),contentPadding=PaddingValues(14.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){items(holder.messages,key={it.id}){m->Row(Modifier.fillMaxWidth(),horizontalArrangement=if(m.senderId==holder.session.user.id)Arrangement.End else Arrangement.Start){Surface(shape=MaterialTheme.shapes.medium,color=if(m.senderId==holder.session.user.id)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant){Text(if(m.messageType=="voice")"رسالة صوتية" else m.body,Modifier.padding(12.dp),color=if(m.senderId==holder.session.user.id)MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant)}}}};if(c.status=="accepted"){Row(Modifier.fillMaxWidth().padding(10.dp),verticalAlignment=Alignment.Bottom){OutlinedTextField(holder.composer,holder::compose,Modifier.weight(1f),placeholder={Text("اكتب رسالة…")});Spacer(Modifier.width(8.dp));Button(onClick={scope.launch{holder.send()}},enabled=holder.composer.isNotBlank()&&!holder.working){Text("إرسال")}}}};return};when(val s=holder.state){DirectUiState.Loading->Box(modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()};is DirectUiState.Error->Column(modifier.fillMaxSize(),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){Text(s.message);Button(onClick={scope.launch{holder.load()}}){Text("حاول تاني")}};is DirectUiState.Ready->if(s.items.isEmpty())Box(modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text("طلبات ومحادثات الناس هتظهر هنا.")}else LazyColumn(modifier.fillMaxSize(),contentPadding=PaddingValues(14.dp)){items(s.items,key={it.id}){c->Card(onClick={scope.launch{holder.open(c)}},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp)){Column(Modifier.padding(14.dp)){Row{Text(c.otherDisplayName?:c.otherUsername?:"مستخدم تِسوى",Modifier.weight(1f),fontWeight=if(c.unreadCount>0)FontWeight.Bold else FontWeight.Medium);if(c.requiresAction)Text("محتاج رد",color=MaterialTheme.colorScheme.primary)};Text(c.lastMessageBody?:if(c.status=="requested")"طلب مراسلة جديد" else "ابدأوا الكلام",maxLines=1,overflow=TextOverflow.Ellipsis,style=MaterialTheme.typography.bodySmall)}}}}}}
